}
.dr-ne:after {
  right: 6px;
  top: 6px;
  border-width: 1.5px 1.5px 0 0;
  border-top-right-radius: 6px;
}
.dr-sw:after {
  left: 6px;
  bottom: 6px;
  border-width: 0 0 1.5px 1.5px;
