.dr-page-controls .dr-icon {display:grid;place-items:center;width:30px;min-width:30px;padding:0;border-radius:4px}
.dr-page-controls :focus-visible {outline:2px solid var(--text);outline-offset:2px}
.dr-review-header {
  display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px 10px;min-width:0;
}
.dr-review-header > :not(.dr-page-controls) {flex:1 1 4em;min-width:min(4em,100%);white-space:normal;overflow-wrap:anywhere}
.dr-review-header h1 {font-size:inherit;font-weight:700}
