.dr-page-controls .dr-choice-compact > .dr-choice-cycle {
  display:flex;align-items:center;justify-content:center;gap:5px;border-radius:3px;min-inline-size:8ch;
}
.dr-page-controls [data-choice=sides] > .dr-choice-cycle {min-inline-size:12ch}
.dr-choice-cycle svg {width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.7;flex:none}
@media (pointer:coarse) {
