    transform:translateY(calc(-1 * var(--dr-header-offset,0px)));transition:none;
  }
  .dr-scroll-header-layout > [data-review-scroll] {
    padding-top:calc(var(--dr-header-height,0px) + var(--dr-preview-top-gap,12px));
    scroll-padding-top:calc(var(--dr-header-height,0px) + var(--dr-preview-top-gap,12px));
    overflow-anchor:none;
  }
}
.dr-navigation .dr-tool-title {margin-right:0;min-width:0;flex-shrink:1;overflow:hidden;text-overflow:ellipsis}
.dr-navigation .dr-utilities {margin-inline-start:auto}
.dr-floating .dr-footer-inner {max-width:none}
.dr-floating .dr-navigation {
  margin:-7px -10px 0;padding:7px 10px 5px;
}
.dr-compose {display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:stretch;gap:8px}
.dr-compose textarea {min-width:0;height:56px;min-height:56px}
.dr-compose button {min-height:30px;height:30px}
.dr-compose [data-dr="commit-comment"]:enabled {background:var(--accent);color:var(--on-accent)}
.dr-save-state:empty {display:none}
.dr-footer .dr-recovery {font:inherit;color:inherit;background:none;border:0;border-radius:2px;box-shadow:none;padding:4px 0;min-height:0;text-decoration:underline;text-underline-offset:2px;cursor:pointer}
.dr-footer .dr-recovery:hover {color:var(--text);background:none}
.dr-compact .dr-selectors {width:100%;box-sizing:border-box}
.dr-footer.dr-compact .dr-selector {flex:1 1 0}
@media (max-width:560px) {
  .dr-page-controls {gap:3px;font-size:12px}
  .dr-page-controls .theme-choices button {padding-inline:5px}
}
.dr-comment-scope {white-space:nowrap;min-width:0}
.dr-comment-scope select {min-width:0}

/* Compact shared drawer: width follows its host; height is controlled by the user. */
.dr-footer:not(.dr-floating) {position:relative;padding:8px 10px max(5px,env(safe-area-inset-bottom))}
.dr-footer:not(.dr-floating)[data-tab] {max-height:none}
.dr-footer-inner {gap:4px;margin:0}
.dr-navigation {gap:3px}
.dr-navigation .dr-icon,.dr-view-tabs .dr-icon {width:28px;min-width:28px;height:28px;min-height:28px}
.dr-navigation .dr-tool-title {font-size:12px;margin-right:8px}
.dr-navigation .dr-selectors {flex:1;min-width:0;margin-inline:4px 12px}
.dr-navigation .dr-selector {flex:1;flex-direction:row;align-items:center;gap:5px}
.dr-navigation .dr-selector label {font-size:11px}
.dr-navigation .dr-selector select {height:26px;min-height:26px}
.dr-navigation .dr-utilities {margin-inline-start:auto;flex-shrink:0}
.dr-view-tabs {margin-right:3px}
.dr-feedback {flex:1;gap:3px}
.dr-compose-actions {display:flex;flex-direction:column;justify-content:space-between;gap:3px}
.dr-entire-review {display:flex;align-items:center;justify-content:flex-start;gap:5px;font-size:12px;min-height:22px;white-space:nowrap;cursor:pointer}
.dr-entire-review input {margin:0;width:14px;height:14px;accent-color:var(--text)}
.dr-action-buttons {display:flex;align-items:center;gap:3px}
.dr-action-buttons .dr-actions {margin-right:6px;gap:3px;flex-wrap:nowrap}
.dr-actions button:not(.dr-icon) {min-width:0;padding:3px 8px;font-size:12px;min-height:28px}
.dr-clear:disabled {display:none}
.dr-note {display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:start;gap:2px 12px;padding:5px 2px}
.dr-note-open {display:grid;text-align:left;gap:2px;border:0!important;border-radius:0;background:none;padding:0;min-height:0;font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere}
.dr-note .dr-save-state {white-space:nowrap;padding-top:1px}
.dr-annotation-card .dr-save-state {font-size:11px;margin-top:4px;color:inherit;opacity:.75}
.dr-annotation-card .dr-recovery {display:inline;width:auto;height:auto;min-height:24px;font:inherit;text-decoration:underline;padding:0}
.dr-height-handle {position:absolute;top:0;left:0;right:0;height:9px;cursor:ns-resize;touch-action:none;z-index:2}
.dr-height-handle::after {content:"";position:absolute;top:2px;left:calc(50% - 20px);width:40px;height:3px;border-radius:2px;background:var(--line)}
.dr-height-handle:hover::after,.dr-height-handle:focus-visible::after {background:var(--muted)}
.dr-floating .dr-height-handle {display:none}
.dr-collapsed .dr-footer-inner > :not(.dr-navigation),.dr-collapsed .dr-selectors {display:none!important}
.dr-collapsed .dr-resize {display:none}
.dr-collapsed .dr-footer-inner {flex:none}
.dr-compact .dr-navigation {flex-wrap:wrap}
.dr-compact .dr-navigation .dr-selectors {order:10;flex:1 0 100%;width:100%;margin:0}
.dr-compact .dr-navigation .dr-selector {flex-direction:column;align-items:stretch;gap:1px}
.dr-compact .dr-compose {grid-template-columns:minmax(0,1fr)}
.dr-compact .dr-compose textarea {height:42px;min-height:42px}
.dr-compact .dr-compose-actions {gap:1px}
.dr-compact .dr-action-buttons .dr-actions {margin-right:auto}
.dr-compact .dr-note {grid-template-columns:minmax(0,1fr)}
.dr-compact .dr-entire-review {min-height:24px}
.dr-compact .dr-action-buttons button {min-height:32px;height:32px}
.dr-compact .dr-note .dr-save-state {white-space:normal}
.dr-page-controls button {min-height:28px}
.dr-page-controls .dr-icon {height:28px}
@container (max-width:1000px) {
  .dr-navigation {flex-wrap:wrap}
  .dr-navigation .dr-selectors {order:10;flex:1 0 100%;width:100%;margin:0}
}
@media (max-width:650px) {
  .dr-footer:not(.dr-floating) {padding-inline:8px}
  .dr-navigation .dr-icon,.dr-view-tabs .dr-icon {height:30px;min-height:30px;width:30px;min-width:30px}
}

