}
export function syncOptionComment(state, {packageId, variationId}, trackEvidence=true) {
  const targets=packageId?[[packageId,variationId]]:Object.entries(state.changes).flatMap(([id,entry])=>Object.keys(entry.options).map(optionId=>[id,optionId]));
  for(const [id,optionId] of targets){
    const draft = state.changes[id]?.options[optionId];
    if (!draft) continue;
    const notes = state.comments.filter(c => (!c.packageId || c.packageId===id && c.variationId===optionId) && c.text.trim());
    draft.comment = notes.map(c => c.text).join('\n');
    if (trackEvidence) draft.commentEvidence = notes.map(({status,reply,...authored}) => copy(authored));
  }
}

export function needsTweaks(state,packageId,variationId) {
  return state.comments?.some(c=>(!c.packageId || c.packageId===packageId && c.variationId===variationId) && c.text.trim() && c.status!=='resolved');
}

export function currentRecords(state, changes) {
  const change=changes.find(c=>c.id===state.currentChangeId);
  const option=change.options.find(o=>o.id===state.activeOptions[change.id]);
  return {change,option,entry:state.changes[change.id],draft:state.changes[change.id].options[option.id]};
}
export function decide(state, changeId, optionId, decision) {
  const entry=state.changes[changeId], option=entry.options[optionId];
  if(decision==='approved') {
    if(state.comments?.some(c=>!c.packageId || c.packageId===changeId && c.variationId===optionId))syncOptionComment(state,{packageId:changeId,variationId:optionId});
    const snapshot=optionSnapshot(option);
    option.approval=copy(snapshot); option.approvalHistory.push({at:new Date().toISOString(),snapshot:copy(snapshot)});
    entry.selectedOptionId=optionId; entry.decision='open';
  } else if(entry.selectedOptionId===optionId) entry.selectedOptionId=null;
  option.decision=decision;
  state.version++;
}
export function exportReview(state, changes) {
  return {
    schemaVersion:4,reviewId:state.reviewId,reviewVersion:state.reviewVersion,
    comments:copy((state.comments || []).filter(note=>note.text.trim())),implementationRequested:false,
    semantics:{approve:'choose this option and exact settings',approvalComments:'required tweaks',reject:'dismiss only this option',commentOnly:'feedback without decision',entireReview:'apply decision to the active variation in each package'},
    changes:changes.map(change=>{
      const entry=state.changes[change.id],chosen=entry.options[entry.selectedOptionId];
      const status=entry.decision==='rejected'?'rejected':!chosen?'open':!approvalCurrent(chosen)?'needs_review':(state.comments ? needsTweaks(state,change.id,entry.selectedOptionId) : chosen.comment.trim())?'required_tweaks':'approved';
      return {id:change.id,title:change.title,status,selectedOptionId:entry.selectedOptionId,options:change.options.map(option=>({id:option.id,title:option.title,...copy(entry.options[option.id]),approvalCurrent:approvalCurrent(entry.options[option.id])}))};
    }),
    view:{currentChangeId:state.currentChangeId,activeOptions:copy(state.activeOptions),sides:state.sides,previewThemes:state.previewThemes,scenes:copy(state.scenes)},
    ...(state.legacyReview?{legacyReview:copy(state.legacyReview)}:{})
  };
}

content.review-example.css:
:root {
  color-scheme: light;
  --bg: #f5f5f5;
  --panel: #fff;
  --text: #151515;
  --muted: #666;
  --line: #d5d5d5;
  --accent: #151515;
  --on-accent: #fff;
  --error: #9c2020;
}
:root[data-theme=dark] {
  color-scheme: dark;
  --bg: #151515;
  --panel: #202020;
  --text: #fafafa;
  --muted: #aaa;
  --line: #494949;
  --accent: #fafafa;
  --on-accent: #151515;
  --error: #ffaaaa;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.4 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
}
button, select, textarea, input {
  font: inherit;
  color: inherit;
}
button, select {
  min-height: 32px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: var(--panel);
  padding: 4px 9px;
}
button {
  cursor: pointer;
  font-weight: 500;
}
button:disabled {
  opacity: .4;
  cursor: default;
}
button:hover:enabled {
  border-color: var(--text);
}
button[aria-pressed=true] {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--on-accent);
}
:focus-visible {
  outline: 2px solid var(--text);
  outline-offset: 2px;
}
h1, h2, h3, strong {
  font-weight: 600;
}
h1 {
  font-size: 15px;
  margin: 0;
  white-space: nowrap;
}
h2 {
  font-size: 18px;
  margin: 0;
}
p {
  margin: 0;
}
a {
  color: inherit;
  text-underline-offset: 3px;
}
.workspace {
  height: 100vh;
  height: 100dvh;
  display: grid;
  grid-template-rows: auto minmax(0,1fr) auto;
}
.review-header {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  padding: 2px 10px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  min-width: 0;
}
main {
  min-width: 0;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  padding: 18px 20px 32px;
}
.content {
  max-width: 1380px;
  margin: auto;
}
.pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}
.pair.compare, .pair.one-theme {
  grid-template-columns: 1fr;
}
.pair.one-theme:not(.compare) {
  max-width: 760px;
  margin: auto;
}
.theme-group {
  min-width: 0;
}
.group-title {
  font-size: 14px;
  color: var(--muted);
  margin-bottom: 6px;
}
.comparison-pair {
  display: grid;
  gap: 16px;
}
.compare .comparison-pair {
  grid-template-columns: repeat(2,minmax(270px,1fr));
  overflow-x: auto;
  align-items: stretch;
}
.preview-column {
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.theme-label {
  font-size: 13px;
  margin-bottom: 6px;
  color: var(--muted);
}
.screen {
  color-scheme: light;
  --s-bg: #fff;
  --s-text: #191b18;
  --s-muted: #62665e;
  --s-line: #d5d8ce;
  --s-surface: #f5f7ef;
  background: var(--s-bg);
  color: var(--s-text);
  border: 1px solid var(--s-line);
  border-radius: 5px;
  min-height: 460px;
  padding: var(--app-padding,24px);
  font-size: var(--app-font,16px);
  display: flex;
  flex: 1;
  flex-direction: column;
}
.screen.dark {
  color-scheme: dark;
  --s-bg: #10121e;
  --s-text: #f6f6fc;
  --s-muted: #b8bdd0;
  --s-line: #434b63;
  --s-surface: #1b1e32;
}
.appbar {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: .875em;
  margin-bottom: 24px;
}
.appbar span:last-child, .date {
  color: var(--s-muted);
}
.screen h3 {
  overflow-wrap: anywhere;
  font-size: var(--app-title,30px);
  letter-spacing: -.6px;
  margin: 0;
  line-height: 1.2;
}
.date {
  font-size: .875em;
  margin: 6px 0 22px;
}
.count {
  display: block;
  font-size: .875em;
  margin-bottom: 12px;
}
.task {
  display: flex;
  align-items: start;
  gap: 12px;
}
.task input {
  accent-color: var(--app-accent);
  flex: none;
  margin: 2px 0 0;
}
.task label {
  font-weight: var(--app-weight);
  flex: 1;
  cursor: pointer;
  min-width: 0;
}
.task small {
  display: block;
  color: var(--s-muted);
  font-size: .875em;
  margin-top: 3px;
}
.task.done label>span {
  text-decoration: line-through;
}
.task.done {
  opacity: .75;
}
.app-action {
  background: var(--app-accent);
  color: var(--app-on-accent);
  border-color: var(--app-accent);
  margin-top: 22px;
  min-height: var(--app-button-height);
  border-radius: var(--app-button-radius);
  padding: 8px 14px;
}
.app-action.full-width {
  width: 100%;
}
.appnav {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: var(--app-label-size);
  color: var(--s-muted);
  margin-top: auto;
  padding-top: var(--app-nav-padding);
}
.appnav strong {
  color: var(--s-text);
}
.appnav>span {
  display: flex;
  align-items: center;
  gap: var(--app-nav-gap);
  padding: 5px;
  min-width: 0;
}
.appnav svg {
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: var(--app-icon-stroke);
}
.appnav.nav-surface {
  background: var(--s-surface);
  padding: var(--app-nav-padding) 8px 8px;
  margin-top: 24px;
}
.appnav.active-fill>span:first-child {
  background: var(--app-accent);
  border-radius: 4px;
  color: var(--app-on-accent);
}
.appnav.active-fill>span:first-child strong {
  color: var(--app-on-accent);
}
.empty {
  padding: 42px 0;
  border-top: 1px solid var(--s-line);
}
.empty strong {
  display: block;
  font-size: 1.25em;
  margin-bottom: 8px;
}
.empty p {
  color: var(--s-muted);
}
.goal-options {
  display: grid;
  margin-top: 20px;
}
.goal-options.inline {
  grid-template-columns: repeat(3,1fr);
}
.goal-options button {
  background: var(--s-surface);
  color: var(--s-text);
  border-color: var(--s-line);
  min-height: var(--app-button-height);
  padding: 10px;
}
.goal-options small {
  display: block;
  font-size: .8em;
  margin-top: 3px;
  color: var(--s-muted);
}
.goal-options button[aria-pressed=true] {
  background: var(--app-accent);
  color: var(--app-on-accent);
}
.goal-options button[aria-pressed=true] small {
  color: var(--app-on-accent);
}
.step {
  display: block;
  font-size: .875em;
  color: var(--s-muted);
  margin-bottom: 8px;
}
.setup-progress {
  height: 4px;
  background: var(--s-surface);
  margin-bottom: 20px;
}
.setup-progress i {
  display: block;
  background: var(--app-accent);
  width: 50%;
  height: 100%;
}
.screen .quiet {
  font-size: .875em;
  color: var(--s-muted);
  margin-top: 12px;
}
.review-detail {
  margin-top: 18px;
  font-size: 13px;
  color: var(--muted);
}
.review-detail summary {
  cursor: pointer;
  width: fit-content;
  padding: 8px 0;
}
.review-detail p {
  margin: 10px 0;
}
textarea {
  display: block;
  width: 100%;
  height: 48px;
  min-height: 36px;
  max-height: 110px;
  resize: vertical;
  padding: 6px 8px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: var(--panel);
  font-size: 13px;
}
.dr-has-floating main {
  padding-bottom: 260px;
}
[hidden] {
  display: none !important;
}
@media (max-width:650px) {
  body {
    font-size: 14px;
  }
  .review-header {
    padding: 2px 8px;
  }
  .dr-has-floating main {
    padding-bottom: 24px;
  }
  main {
    padding: 12px 10px 24px;
  }
  .pair {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .screen {
    min-height: 460px;
  }
  .compare .comparison-pair {
    gap: 10px;
  }
  .appnav>span {
    flex-direction: column;
  }
  .goal-options.inline {
    grid-template-columns: 1fr;
  }
}
@media (prefers-reduced-motion:reduce) {
  * {
    scroll-behavior: auto;
  }
}
[data-dr=quote] {
  font-size: 11px;
  color: var(--muted);
}

